function typeformInvoiceData({ response, invoiceDefaults, templateId }) {
  if (
    !response ||
    typeof response !== "object" ||
    !Array.isArray(response.answers) ||
    response.answers.length < 6
  )
    throw new Error("Expected the six invoice answers in the configured form order");
  const answers = response.answers;
  const text = (index, type) => {
    const answer = answers[index];
    if (!answer || answer.type !== type || typeof answer[type] !== "string" || !answer[type].trim())
      throw new Error("Missing or invalid invoice answer at position " + (index + 1));
    return answer[type];
  };
  const amount = (index) => {
    const answer = answers[index];
    if (
      !answer ||
      answer.type !== "number" ||
      typeof answer.number !== "number" ||
      !Number.isFinite(answer.number)
    )
      throw new Error("Missing or invalid invoice amount at position " + (index + 1));
    return "EUR " + answer.number;
  };
  const fields = [
    "company",
    "invoice_no",
    "invoice_date",
    "invoice_due_date",
    "address",
    "website",
    "document_id",
  ];
  if (!invoiceDefaults || typeof invoiceDefaults !== "object" || Array.isArray(invoiceDefaults))
    throw new Error("Configure the invoice issuer and document fields");
  const body = {};
  for (const field of fields) {
    if (typeof invoiceDefaults[field] !== "string" || !invoiceDefaults[field].trim())
      throw new Error("Configure invoice field " + field);
    body[field] = invoiceDefaults[field];
  }
  body.email = text(1, "email");
  body.company_bill_to = text(0, "text");
  body.items = [
    { item_name: text(2, "text"), price: amount(3) },
    { item_name: text(4, "text"), price: amount(5) },
  ];
  if (typeof templateId !== "string" || !templateId.trim())
    throw new Error("Configure the PDF template ID");
  return {
    body,
    url: "https://api.apitemplate.io/v1/create?template_id=" + encodeURIComponent(templateId),
  };
}

if ($json.event_type !== "form_response") throw new Error("Expected a completed Typeform response");
return {
  json: typeformInvoiceData({
    response: $json.form_response,
    invoiceDefaults: {
      company: "YOUR_COMPANY",
      invoice_no: "CONFIGURE_INVOICE_NUMBER",
      invoice_date: "CONFIGURE_INVOICE_DATE",
      invoice_due_date: "CONFIGURE_DUE_DATE",
      address: "YOUR_COMPANY_ADDRESS",
      website: "https://example.com",
      document_id: "CONFIGURE_DOCUMENT_ID",
    },
    templateId: "YOUR_PDF_TEMPLATE_ID",
  }),
};
